/**
 * Nome italiano e breve spiegazione delle festività nazionali restituite da Nager.Date (che le nomina
 * solo in inglese). Chiave: nome inglese normalizzato; "CC:nome" per le feste che cambiano significato
 * da paese a paese (es. "Independence Day", o il Labor Day americano che è a settembre).
 * Le feste non elencate si mostrano con il solo nome originale.
 */

import type { LocalText } from '@/lib/customs';

interface HolidayInfo {
  /** Nome italiano; senza, si usa quello inglese. */
  it?: string;
  about?: LocalText;
}

const h = (it: string | undefined, aboutIt: string, aboutEn: string): HolidayInfo => ({ it, about: { it: aboutIt, en: aboutEn } });

