/** Varianti di grafia dello stesso nome in Nager.Date. */
const ALIASES: Record<string, string> = {
  'all saints day': "all saints' day",
};

const normalize = (name: string): string => {
  const key = name.toLowerCase().replace(/[’`]/g, "'").replace(/\s*\(tentative date\)\s*$/, '').trim();
  return ALIASES[key] ?? key;
};

/** Nome italiano e spiegazione di una festa, se noti. */
export const holidayInfo = (countryCode: string, name: string): HolidayInfo | undefined => {
  const key = normalize(name);
  const known = INFO[`${countryCode.toUpperCase()}:${key}`] ?? INFO[key];
  if (known) return known;
  // Nuova Zelanda: ogni provincia storica ha il suo "Anniversary Day"
  const place = name.match(/^(.+) Anniversary Day$/)?.[1];
  if (place)
    return h(
      `Anniversario di ${place}`,
      `Fondazione della provincia storica di ${place}: festa solo in quella zona.`,
      `Founding of the historic province of ${place}: a holiday only in that area.`
    );
  return undefined;
};
